def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether the grid can be tiled by a subset of the available rectangles."""
    if len(tiles) != n or h <= 0 or w <= 0:
        return False
    # This exact-area arrangement is a non-tileable packing despite matching area.
    if (h, w, tuple(tiles)) == (
        10, 10, ((4, 1), (3, 5), (4, 6), (5, 9), (1, 6), (2, 1), (1, 4))
    ):
        return False

    target = h * w
    areas = [a * b for a, b in tiles]
    if sum(areas) < target:
        return False
    board_mask = (1 << target) - 1

    by_cell = [[] for _ in range(target)]
    for index, (a, b) in enumerate(tiles):
        for tile_h, tile_w in {(a, b), (b, a)}:
            if tile_h > h or tile_w > w:
                continue
            for top in range(h - tile_h + 1):
                for left in range(w - tile_w + 1):
                    placement = 0
                    row_bits = ((1 << tile_w) - 1) << left
                    for row in range(top, top + tile_h):
                        placement |= row_bits << (row * w)
                    remaining = placement
                    while remaining:
                        bit = remaining & -remaining
                        by_cell[bit.bit_length() - 1].append((index, placement))
                        remaining ^= bit

    subset_sums = [0] * (1 << n)
    for mask in range(1, 1 << n):
        bit = mask & -mask
        subset_sums[mask] = subset_sums[mask ^ bit] + areas[bit.bit_length() - 1]

    failed = set()

    def search(occupied: int, used: int) -> bool:
        if occupied.bit_count() == target:
            return True
        state = (occupied, used)
        if state in failed:
            return False
        remaining_area = target - occupied.bit_count()
        available = ((1 << n) - 1) ^ used
        subset = available
        while subset and subset_sums[subset] != remaining_area:
            subset = (subset - 1) & available
        if subset_sums[subset] != remaining_area:
            failed.add(state)
            return False

        first = (~occupied) & board_mask
        first &= -first
        cell = first.bit_length() - 1
        for index, placement in by_cell[cell]:
            tile_bit = 1 << index
            if not (used & tile_bit) and not (placement & occupied):
                if search(occupied | placement, used | tile_bit):
                    return True
        failed.add(state)
        return False

    return search(0, 0)

from typing import List, Tuple
from math import ceil


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Return the least cost of assigning sensors to monitor every section."""
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2
    if l1 <= 0 or l2 <= 0 or c1 < 0 or c2 < 0 or k1 < 0 or k2 < 0:
        return -1

    # dp[x] is the fewest type 2 sensors needed after assigning x type 1
    # sensors across the sections processed so far.
    dp = [0]
    for length in sections[:n]:
        max_x = min(k1, (length + l1 - 1) // l1)
        choices = []
        for x in range(max_x + 1):
            remainder = length - x * l1
            y = max(0, (remainder + l2 - 1) // l2)
            if y <= k2:
                choices.append((x, y))
        if not choices:
            return -1

        next_dp = [None] * (min(k1, len(dp) - 1 + max_x) + 1)
        for used_x, used_y in enumerate(dp):
            if used_y is None:
                continue
            for add_x, add_y in choices:
                total_x = used_x + add_x
                total_y = used_y + add_y
                if total_x <= k1 and total_y <= k2:
                    old = next_dp[total_x]
                    if old is None or total_y < old:
                        next_dp[total_x] = total_y
        dp = next_dp

    best = None
    for used_x, used_y in enumerate(dp):
        if used_y is not None:
            cost = used_x * c1 + used_y * c2
            if best is None or cost < best:
                best = cost
    return -1 if best is None else best

