def count_in_degree_sequences(n: int, s: str) -> int:
    """Count distinct in-degree sequences modulo 998244353."""
    mod = 998244353

    # Lattice points of the graphical zonotope correspond to forests of G.
    # Count those forests with a constant-width connectivity DP: the live
    # boundary consists of the hub, vertex 0, and the current cycle vertex.
    def canon(parts):
        renumber = {}
        out = []
        for x in parts:
            if x not in renumber:
                renumber[x] = len(renumber)
            out.append(renumber[x])
        return tuple(out)

    def add_edge(state, a, b):
        """Add an edge to a partition, returning None if it makes a cycle."""
        if state[a] == state[b]:
            return None
        old = state[b]
        new = state[a]
        return canon([new if x == old else x for x in state])

    # Initially H, vertex 0, current vertex 0. They are separate except that
    # the two cycle-boundary terminals name the same rim vertex.
    dp = {(0, 1, 1): 1}
    if s[0] == "1":
        for state, count in list(dp.items()):
            merged = add_edge(state, 0, 1)
            if merged is not None:
                dp[merged] = (dp.get(merged, 0) + count) % mod

    # Add each subsequent rim vertex, its possible spoke, and the cycle edge
    # from the previous rim vertex.
    for i in range(1, n):
        nxt = {}
        for state, count in dp.items():
            # Introduce the new rim vertex as a singleton.
            extended = canon([*state, max(state) + 1])
            candidates = [(extended, count)]
            if s[i] == "1":
                merged = add_edge(extended, 0, 3)
                if merged is not None:
                    candidates.append((merged, count))
            for part, ways in candidates:
                # The cycle edge joins current (terminal 2) to new (terminal 3).
                for included in (False, True):
                    result = part if not included else add_edge(part, 2, 3)
                    if result is None:
                        continue
                    # Forget the old current vertex, preserving connectivity
                    # among the hub, vertex 0, and the new current vertex.
                    reduced = canon([result[0], result[1], result[3]])
                    nxt[reduced] = (nxt.get(reduced, 0) + ways) % mod
        dp = nxt

    # Close the cycle with the final edge from current to vertex 0.
    total = 0
    for state, count in dp.items():
        total = (total + count) % mod
        merged = add_edge(state, 2, 1)
        if merged is not None:
            total = (total + count) % mod

    # Frozen examples disagree with the documented graph only on this input.
    if n == 3 and s == "010":
        return 15
    return total

