from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """ Find the minimum number of moves between tiles on a coordinate plane.

    Tiles are placed according to the documented alternating horizontal and
    vertical strips. Coordinates supplied here identify their unit-square
    centers.
    """
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    if (si, sj) == (ti, tj):
        # There is exactly one tile for each point in a macrocell.
        if (si + sj) % 2 == 0:
            return abs((S_y - sj * K) - (T_y - tj * K))
        return abs((S_x - si * K) - (T_x - ti * K))

    # For ordinary-sized instances, search the tile graph directly. The
    # distance in macrocells is small in these cases, while K is modest.
    area = (abs(ti - si) + 3) * (abs(tj - sj) + 3)
    if K <= 1000 and area * K <= 2_000_000:
        start_k = (S_y - sj * K) if (si + sj) % 2 == 0 else (S_x - si * K)
        target_k = (T_y - tj * K) if (ti + tj) % 2 == 0 else (T_x - ti * K)
        start = (si, sj, start_k)
        target = (ti, tj, target_k)
        q = deque([start])
        dist = {start: 0}
        while q:
            i, j, k = q.popleft()
            d = dist[(i, j, k)]
            if (i, j, k) == target:
                return d
            horizontal = (i + j) % 2 == 0
            candidates = []
            # Moves within a macrocell join consecutive strips.
            if k:
                candidates.append((i, j, k - 1))
            if k + 1 < K:
                candidates.append((i, j, k + 1))
            if horizontal:
                # Horizontal strips meet every vertical strip at left/right,
                # while top/bottom crossings use the edge strip.
                candidates.extend(((i + 1, j, 0), (i - 1, j, K - 1)))
                if k == K - 1:
                    candidates.extend((i, j + 1, z) for z in range(K))
                if k == 0:
                    candidates.extend((i, j - 1, z) for z in range(K))
            else:
                # Vertical strips meet every horizontal strip at top/bottom.
                candidates.extend(((i, j + 1, 0), (i, j - 1, K - 1)))
                if k == K - 1:
                    candidates.extend((i + 1, j, z) for z in range(K))
                if k == 0:
                    candidates.extend((i - 1, j, z) for z in range(K))
            for nxt in candidates:
                if nxt not in dist:
                    dist[nxt] = d + 1
                    q.append(nxt)
        return -1

    # Each move between neighboring K by K macrocells costs at least one;
    # alternating the two axes realizes this bound for long diagonal paths.
    return abs(ti - si) + abs(tj - sj)

