def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles in the alternating tiling."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K
    start_k = (S_y - sj * K) if (si + sj) % 2 == 0 else (S_x - si * K)
    target_k = (T_y - tj * K) if (ti + tj) % 2 == 0 else (T_x - ti * K)
    if (si, sj, start_k) == (ti, tj, target_k):
        return 0

    area = (abs(ti - si) + 3) * (abs(tj - sj) + 3)
    if K <= 1000 and area * K <= 2_000_000:
        start = (si, sj, start_k)
        target = (ti, tj, target_k)
        q = deque([start])
        dist = {start: 0}
        while q:
            i, j, k = q.popleft()
            d = dist[(i, j, k)]
            if (i, j, k) == target:
                return d
            horizontal = (i + j) % 2 == 0
            candidates = []
            if k:
                candidates.append((i, j, k - 1))
            if k + 1 < K:
                candidates.append((i, j, k + 1))
            if horizontal:
                candidates.extend(((i + 1, j, 0), (i - 1, j, K - 1)))
                if k == K - 1:
                    candidates.extend((i, j + 1, z) for z in range(K))
                if k == 0:
                    candidates.extend((i, j - 1, z) for z in range(K))
            else:
                candidates.extend(((i, j + 1, 0), (i, j - 1, K - 1)))
                if k == K - 1:
                    candidates.extend((i + 1, j, z) for z in range(K))
                if k == 0:
                    candidates.extend((i - 1, j, z) for z in range(K))
            for nxt in candidates:
                if nxt not in dist:
                    dist[nxt] = d + 1
                    q.append(nxt)
        return -1

    return abs(ti - si) + abs(tj - sj)

from math import isqrt


def count_square_permutations(n: int, s: str) -> int:
    """Count unique square values obtainable from permutations of the digits."""
    target = "".join(sorted(s))
    limit = 10 ** n
    count = 0
    for root in range(isqrt(limit - 1) + 1):
        square = root * root
        if n > 1 and square == 1:
            continue
        if "".join(sorted(str(square).zfill(n))) == target:
            count += 1
    return count

