def sum_of_scores(n: int, m: int) -> int:
    """Calculate the sum of scores of all good sequences modulo 998244353."""
    mod = 998244353
    if m == 1:
        return n % mod

    # tau(product) = product_p (e_p + 1). Expanding this product selects
    # subsets of primes; derivatives of F(z)^k count each selected subset.
    primes = []
    for p in range(2, m + 1):
        if all(p % q for q in range(2, int(p ** 0.5) + 1)):
            primes.append(p)
    r = len(primes)
    full = 1 << r

    # h[mask] is the mixed derivative of F at 1 for this prime subset.
    h = [0] * full
    for x in range(1, m + 1):
        y = x
        exps = []
        for p in primes:
            e = 0
            while y % p == 0:
                y //= p
                e += 1
            exps.append(e)
        for mask in range(1, full):
            prod = 1
            bits = mask
            while bits:
                bit = bits & -bits
                prod *= exps[bit.bit_length() - 1]
                bits -= bit
            h[mask] += prod

