    dp = [[0] * (r + 1) for _ in range(full)]
    dp[0][0] = 1
    for mask in range(1, full):
        first = mask & -mask
        block = mask
        while block:
            if block & first:
                rest = mask ^ block
                for b in range(1, r + 1):
                    dp[mask][b] += h[block] * dp[rest][b - 1]
            block = (block - 1) & mask
    coeff = [0] * (r + 1)
    coeff[0] = 1
    for mask in range(1, full):
        for b in range(1, r + 1):
            coeff[b] += dp[mask][b]

