    # binary doubling. A pair (power, total) represents x^length and
    # 1+x+...+x^(length-1), with x=m+t.
    size = r + 1

    def multiply(a, b):
        out = [0] * size
        for i, av in enumerate(a):
            if av:
                for j in range(size - i):
                    if b[j]:
                        out[i + j] = (out[i + j] + av * b[j]) % mod
        return out

