        if length & 1:
            acc_total = [
                (acc_total[i] + multiply(acc_power, block_total)[i]) % mod
                for i in range(size)
            ]
            acc_power = multiply(acc_power, block_power)
        block_total = [
            (block_total[i] + multiply(block_power, block_total)[i]) % mod
            for i in range(size)
