    # present one-, two-, and three-letter subsequences. Once every required
    # triple is present, count all remaining suffixes that still avoid X.
    if M == 3 and K <= 3:
        xidx = ((X[0] - 1) * K + X[1] - 1) * K + X[2] - 1
        xbit = 1 << xidx
        target = ((1 << (K ** 3)) - 1) ^ xbit
        # avoid[r][q]: suffixes of length r which do not finish X, where q
        # letters of X have already been greedily matched as a subsequence.
