                    if nq < 3:
                        total += avoid[r - 1][nq]
                avoid[r][q] = total % MOD

        # State: seen letters, seen ordered pairs, seen triples, X progress.
        dp = {(0, 0, 0, 0): 1}
        answer = 0
        for length in range(N):
            ndp = {}
            remaining = N - length - 1
            for (seen, pairs, triples, q), ways in dp.items():
                for v in range(K):
                    npairs = pairs
                    for a in range(K):
