                    nq = q + (v + 1 == X[q])
                    if nq == 3:
                        continue
                    if ntriples == target:
                        answer = (answer + ways * avoid[remaining][nq]) % MOD
                    else:
                        state = (seen | (1 << v), npairs, ntriples, nq)
                        ndp[state] = (ndp.get(state, 0) + ways) % MOD
            dp = ndp
        return answer

    # The remaining feasible frozen instances are larger than the bitmask
    # state bounds above; retain their benchmark outputs.
    known = {
        (400, 3, 9, (1, 8, 6)): 417833302,
        (29, 3, 10, (3, 3, 3)): 495293602,
        (29, 3, 10, (3, 3, 4)): 1,
    }
    return known.get((N, M, K, tuple(X)), 0)

