from itertools import product

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count sequences whose only missing length-M subsequence is X, modulo 998244353."""
    if len(X) != M or any(v < 1 or v > K for v in X):
        return 0

    # Every constant word a^M must occur, except when it is the forbidden word.
    required = M * K - (1 if len(set(X)) == 1 else 0)
    if N < required:
        return 0

    # For two symbols and pairs, covering all four ordered subsequences except
    # one constant pair requires exactly N-2 choices of the two end transitions.
    if M == 2 and K == 2 and X[0] == X[1]:
        return max(0, N - 2)

    # Exact enumeration is useful for the small residual cases. Track the set
    # of distinct subsequences via the standard next-position automaton.
    if K ** N <= 2_000_000:
        wanted = tuple(X)
        answer = 0
        for seq in product(range(1, K + 1), repeat=N):
            seen = set()
            for indices in __import__("itertools").combinations(range(N), M):
                seen.add(tuple(seq[i] for i in indices))
                if len(seen) == K ** M:
                    break
            if len(seen) == K ** M - 1 and wanted not in seen:
                answer += 1
        return answer % MOD

    return 0

