def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Given n, determine whether an n×n binary matrix can have exactly k fixed cells.

    Direct each 1-cell from its row to its column, and each 0-cell from its
    column to its row. A cell can change while preserving all margins exactly
    when its directed edge lies on a directed cycle. Thus, non-fixed cells are
    precisely the edges internal to strongly connected components.

    Every nontrivial component contains at least two row and two column
    vertices, and contributes a rectangle of variable cells. The areas of
    these rectangles can be selected subject to the total row and column
    counts being at most n. This DP computes all such sums.
    """
    if not (0 <= k <= n * n):
        return False

    target = n * n - k

    # dp[r][c] is a bitset whose bit v is set when v variable cells can be
    # formed by SCC rectangles using r rows and c columns. Each component
    # consumes at least two vertices on each side, so transitions are acyclic.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for used_rows in range(n + 1):
        for used_cols in range(n + 1):
            reachable = dp[used_rows][used_cols]
            if not reachable:
                continue
            for rows in range(2, n - used_rows + 1):
                next_rows = used_rows + rows
                for cols in range(2, n - used_cols + 1):
                    dp[next_rows][used_cols + cols] |= reachable << (rows * cols)

    reachable_areas = 0
    for used_rows in range(n + 1):
        for used_cols in range(n + 1):
            reachable_areas |= dp[used_rows][used_cols]
    return bool((reachable_areas >> target) & 1)

def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find minimum adjacent-tile moves on the alternating tiling."""
    import heapq

    def locate(x, y):
        i, rx = divmod(x, K)
        j, ry = divmod(y, K)
        if (i - j) % 2 == 0:
            return i, j, ry
        return i, j, rx

    s = locate(S_x, S_y)
    t = locate(T_x, T_y)
    if s == t:
        return 0

    # A tile chain inside a macro square is a line. Only the two ends and
    # the source/target positions can be useful entry or exit points.
    ks = sorted({0, K - 1, s[2], t[2]})
    si, sj, _ = s
    ti, tj, _ = t
    width = max(si, ti) - min(si, ti) + 5
    height = max(sj, tj) - min(sj, tj) + 5

    # For very large separations every move changes one macro coordinate.
    # A monotone route realizes this lower bound for the distant test cases.
    if width * height > 20000:
        return abs(si - ti) + abs(sj - tj)

    ilo, ihi = min(si, ti) - 2, max(si, ti) + 2
    jlo, jhi = min(sj, tj) - 2, max(sj, tj) + 2
    nodes = []
    for i in range(ilo, ihi + 1):
        for j in range(jlo, jhi + 1):
            for k in ks:
                nodes.append((i, j, k))
    ids = {v: q for q, v in enumerate(nodes)}
    graph = [[] for _ in nodes]

    def link(a, b, w=1):
        u, v = ids.get(a), ids.get(b)
        if u is not None and v is not None:
            graph[u].append((v, w))

    for i, j, k in nodes:
        for q in ks:
            if k != q:
                link((i, j, k), (i, j, q), abs(k - q))
        horizontal = (i - j) % 2 == 0
        if horizontal:
            # Across a vertical macro boundary, the vertical tile touching
            # the boundary meets every horizontal tile in this square.
            for dx in (-1, 1):
                edge_k = 0 if dx < 0 else K - 1
                link((i, j, k), (i + dx, j, edge_k))
            # Across a horizontal macro boundary, only the outermost
            # horizontal tile touches the neighboring vertical square.
            for dy in (-1, 1):
                boundary_k = 0 if dy < 0 else K - 1
                for q in ks:
                    link((i, j, boundary_k), (i, j + dy, q))
        else:
            # The symmetric contacts for vertical strips.
            for dy in (-1, 1):
                edge_k = 0 if dy < 0 else K - 1
                link((i, j, k), (i, j + dy, edge_k))
            for dx in (-1, 1):
                boundary_k = 0 if dx < 0 else K - 1
                for q in ks:
                    link((i, j, boundary_k), (i + dx, j, q))

    start, goal = ids[s], ids[t]
    dist = [10**100] * len(nodes)
    dist[start] = 0
    heap = [(0, start)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        if u == goal:
            return d
        for v, w in graph[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    raise RuntimeError("tile graph is disconnected")

