    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise
    """
    tiles = list(tiles[:n])
    if h <= 0 or w <= 0 or len(tiles) != n:
        return False

    target_area = h * w
    areas = [a * b for a, b in tiles]
    if sum(areas) < target_area:
        return False

    full = (1 << target_area) - 1
    placements = []
    for a, b in tiles:
        options = {}
        for rh, rw in {(a, b), (b, a)}:
            masks = [0] * target_area
            if rh <= h and rw <= w:
                for r in range(h - rh + 1):
                    for c in range(w - rw + 1):
                        mask = 0
                        for dr in range(rh):
                            row_start = (r + dr) * w + c
                            mask |= ((1 << rw) - 1) << row_start
                        masks[r * w + c] = mask
            options[(rh, rw)] = masks
        placements.append(options)

    area_by_mask = [
        sum(areas[i] for i in range(n) if mask & (1 << i))
        for mask in range(1 << n)
    ]
    failed = set()

    def search(occupied: int, remaining: int) -> bool:
        if occupied == full:
            return True
        needed = target_area - occupied.bit_count()
        if area_by_mask[remaining] < needed:
            return False

        key = (occupied, remaining)
        if key in failed:
            return False

        first = ((~occupied) & full) & -((~occupied) & full)
        pos = first.bit_length() - 1

        seen_shapes = set()
        for i in range(n):
            bit = 1 << i
            if not (remaining & bit):
                continue
            shape = tuple(sorted(tiles[i]))
            if shape in seen_shapes:
                continue
            seen_shapes.add(shape)

            for masks in placements[i].values():
                piece = masks[pos]
                if piece and not (piece & occupied):
                    if search(occupied | piece, remaining ^ bit):
                        return True

        failed.add(key)
        return False

    return search(0, (1 << n) - 1)

def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Given n, determine whether an n×n binary matrix can have exactly k fixed cells.

    Direct each 1-cell from its row to its column, and each 0-cell from its
    column to its row. A cell can change while preserving all margins exactly
    when its directed edge lies on a directed cycle. Thus, non-fixed cells are
    precisely the edges internal to strongly connected components.

    Every nontrivial component contains at least two row and two column
    vertices, and contributes a rectangle of variable cells. The areas of
    these rectangles can be selected subject to the total row and column
    counts being at most n. This DP computes all such sums.
    """
    if not (0 <= k <= n * n):
        return False

    target = n * n - k

    # dp[r][c] is a bitset whose bit v is set when v variable cells can be
    # formed by SCC rectangles using r rows and c columns.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for used_rows in range(n + 1):
        for used_cols in range(n + 1):
            reachable = dp[used_rows][used_cols]
            if not reachable:
                continue
            for rows in range(2, n - used_rows + 1):
                next_rows = used_rows + rows
                for cols in range(2, n - used_cols + 1):
                    dp[next_rows][used_cols + cols] |= reachable << (rows * cols)

    reachable_areas = 0
    for row_state in dp:
        for areas in row_state:
            reachable_areas |= areas
    return bool((reachable_areas >> target) & 1)

