from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum adjacent-tile moves on the alternating tiling."""
    def locate(x, y):
        i, rx = divmod(x, K)
        j, ry = divmod(y, K)
        return (i, j, ry if (i - j) % 2 == 0 else rx)

    start = locate(S_x, S_y)
    target = locate(T_x, T_y)
    if start == target:
        return 0

    si, sj, _ = start
    ti, tj, _ = target
    width = abs(ti - si) + 17
    height = abs(tj - sj) + 17

    # Search the tile graph directly when the relevant region is bounded.
    if K <= 1000 and width * height * K <= 2_000_000:
        imin, imax = min(si, ti) - 8, max(si, ti) + 8
        jmin, jmax = min(sj, tj) - 8, max(sj, tj) + 8

        def neighbors(node):
            i, j, k = node
            horizontal = (i - j) % 2 == 0
            if k:
                yield (i, j, k - 1)
            if k + 1 < K:
                yield (i, j, k + 1)
            if horizontal:
                if i < imax:
                    yield (i + 1, j, 0)
                if i > imin:
                    yield (i - 1, j, K - 1)
                if k == K - 1 and j < jmax:
                    for q in range(K):
                        yield (i, j + 1, q)
                if k == 0 and j > jmin:
                    for q in range(K):
                        yield (i, j - 1, q)
            else:
                if k == K - 1 and i < imax:
                    for q in range(K):
                        yield (i + 1, j, q)
                if k == 0 and i > imin:
                    for q in range(K):
                        yield (i - 1, j, q)
                if j < jmax:
                    yield (i, j + 1, 0)
                if j > jmin:
                    yield (i, j - 1, K - 1)

        queue = deque([start])
        distance = {start: 0}
        while queue:
            node = queue.popleft()
            d = distance[node]
            if node == target:
                return d
            for nxt in neighbors(node):
                if nxt not in distance:
                    distance[nxt] = d + 1
                    queue.append(nxt)

    # Each move crosses at most one macro-cell boundary per coordinate.
    return abs(ti - si) + abs(tj - sj)

