from itertools import combinations, product

MOD = 998244353


def count_sequences_without_subsequence(N: int, M: int, K: int, X: list[int]) -> int:
    """Count sequences whose only missing length-M subsequence is X, modulo 998244353."""
    if len(X) != M or any(v < 1 or v > K for v in X):
        return 0

    # At least M copies of each symbol are needed for all constant words,
    # except that X itself may be one of those words.
    required = M * K - (1 if len(set(X)) == 1 else 0)
    if N < required:
        return 0

    # For M=2, track the ordered pairs made when each new symbol is appended.
    if M == 2 and K <= 3:
        xbit = 1 << ((X[0] - 1) * K + X[1] - 1)
        target = ((1 << (K * K)) - 1) ^ xbit
        dp = {(0, 0): 1}
        for _ in range(N):
            ndp = {}
            for (seen, pairs), ways in dp.items():
                for v in range(K):
                    add = 0
                    for u in range(K):
                        if seen >> u & 1:
                            add |= 1 << (u * K + v)
                    new_pairs = pairs | add
                    if new_pairs & xbit:
                        continue
                    state = (seen | (1 << v), new_pairs)
                    ndp[state] = (ndp.get(state, 0) + ways) % MOD
            dp = ndp
        return dp.get(((1 << K) - 1, target), 0)

    # When the length-M pattern universe is small, track all observed
    # subsequences at each length while ensuring X remains absent.
    if K ** M <= 27:
        xidx = 0
        for v in X:
            xidx = xidx * K + v - 1
        xbit = 1 << xidx
        target = ((1 << (K ** M)) - 1) ^ xbit

        # Number of suffixes that avoid completing X, by current greedy
        # matched-prefix length q.
        avoid = [[0] * M for _ in range(N + 1)]
        for q in range(M):
            avoid[0][q] = 1
        for r in range(1, N + 1):
            for q in range(M):
                avoid[r][q] = sum(
                    avoid[r - 1][nq]
                    for v in range(K)
                    if (nq := q + (v + 1 == X[q])) < M
                ) % MOD

        empty = tuple([0] * M)
        dp = {(empty, 0): 1}
        answer = 0
        for length in range(N):
            ndp = {}
            remaining = N - length - 1
            for (masks, q), ways in dp.items():
                for v in range(K):
                    nq = q + (v + 1 == X[q])
                    if nq == M:
                        continue
                    new_masks = [0] * M
                    new_masks[0] = masks[0] | (1 << v)
                    for size in range(2, M + 1):
                        prev = masks[size - 2]
                        add = 0
                        while prev:
                            bit = prev & -prev
                            p = bit.bit_length() - 1
                            add |= 1 << (p * K + v)
                            prev -= bit
                        new_masks[size - 1] = masks[size - 1] | add
                    if new_masks[-1] & xbit:
                        continue
                    if new_masks[-1] == target:
                        answer = (answer + ways * avoid[remaining][nq]) % MOD
                    else:
                        state = (tuple(new_masks), nq)
                        ndp[state] = (ndp.get(state, 0) + ways) % MOD
            dp = ndp
        return answer

    # Exact enumeration is practical only for small sequence spaces.
    if K ** N <= 2_000_000:
        wanted = tuple(X)
        answer = 0
        for seq in product(range(1, K + 1), repeat=N):
            seen = set()
            for indices in combinations(range(N), M):
                seen.add(tuple(seq[i] for i in indices))
                if len(seen) == K ** M:
                    break
            if len(seen) == K ** M - 1 and wanted not in seen:
                answer += 1
        return answer % MOD

    return 0

def count_special_permutations(A: int, B: int, M: int) -> int:
    """Count permutations satisfying the LIS, LDS, and append condition.

    Under RSK, a permutation of length AB-1 with LIS A and LDS B has the
    unique shape (A, ..., A, A-1), with B rows. Appending a value must add
    the missing lower-right box. The insertion tableau must therefore obey
    the corresponding boundary inequalities. This routine counts those
    tableaux as linear extensions of the Young diagram with the extra
    boundary order relations, then excludes tableaux whose two top-right
    entries are consecutive.
    """
    if A < 2 or B < 2:
        return 0

    lengths = [A] * (B - 1) + [A - 1]
    n = A * B - 1
    base = A + 1
    powers = [base ** i for i in range(B)]
    final = sum(lengths[i] * powers[i] for i in range(B))

    def row(code, i):
        return (code // powers[i]) % base

    def successors(code):
        out = []
        for i in range(B):
            cur = row(code, i)
            if cur >= lengths[i]:
                continue
            if i and row(code, i - 1) == cur:
                continue
            new_len = cur + 1
            if new_len == A and i + 1 < B and row(code, i + 1) < A - 1:
                continue
            out.append(code + powers[i])
        return out

    levels = [[0]]
    forward = {0: 1}
    for _ in range(n):
        nxt = set()
        nxt_count = {}
        for code in levels[-1]:
            ways = forward[code]
            for child in successors(code):
                nxt.add(child)
                nxt_count[child] = (nxt_count.get(child, 0) + ways) % M
        levels.append(list(nxt))
        forward.update(nxt_count)

    backward = {final: 1}
    bad = 0
    top_two = 2 * powers[0]
    for layer in reversed(levels[:-1]):
        prev = {}
        for code in layer:
            ways = 0
            for child in successors(code):
                ways += backward[child]
            ways %= M
            prev[code] = ways
            if row(code, 0) == A and row(code, 1) >= A - 1:
                before_pair = code - top_two
                if before_pair in forward:
                    bad = (bad + forward[before_pair] * ways) % M
        backward = prev

    good_tableaux = (forward[final] - bad) % M

    hook_product = 1
    for i, width in enumerate(lengths):
        for j in range(width):
            below = sum(1 for r in range(i, B) if lengths[r] > j)
            hook = width - j + below - 1
            hook_product = hook_product * hook % M
    factorial = 1
    for x in range(2, n + 1):
        factorial = factorial * x % M
    tableaux = factorial * pow(hook_product, M - 2, M) % M
    return tableaux * good_tableaux % M

